#!/usr/bin/env python3
import csv
import json
import sys
from pathlib import Path
from datetime import datetime, timezone

PAGE = '<!doctype html>\n<html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hermes Evaluation Results</title>\n<style>\nbody{font:16px system-ui,sans-serif;background:#101722;color:#e7edf5;margin:0;padding:28px}h1{margin-top:0}p{max-width:1000px;line-height:1.5;color:#b9c9dc}select,input,button{font:inherit;background:#202d40;color:#fff;border:1px solid #52657d;border-radius:6px;padding:10px}input{min-width:260px}label{display:inline-block;margin:8px 12px 8px 0}.scroll{overflow:auto;max-height:70vh;border:1px solid #35475e;margin-top:18px}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;padding:12px;border-bottom:1px solid #35475e;white-space:nowrap}th{position:sticky;top:0;background:#202d40}th button{border:0;padding:0;background:transparent;text-align:left}tr:nth-child(even){background:#162131}.good{color:#8ee0ad}.bad{color:#ffb5a7}#count{margin-top:10px}small{color:#afbdd0}button:focus,input:focus,select:focus{outline:2px solid #8ac4ff}\n</style>\n<h1>Hermes Evaluation Results</h1>\n<p>Local, offline snapshot of saved evaluations. No inference requests, remote assets, or server. Click a column heading to sort; click again to reverse. Use the search box to filter.</p>\n<p><strong>Smoke-test results, not a general model leaderboard.</strong> Success is task-specific. Timing is split into total workflow (includes container startup and trace export), agent-process (monotonic clock), and session-reported seconds; these are not interchangeable. Unknown settings were not independently captured. Compare equivalent tasks and configurations; one passing attempt does not establish reliability. Runs are grouped by a code fingerprint of the evaluation code and task, so documentation-only commits do not split a group; runs without a recorded fingerprint show unknown provenance.</p>\n<label>View <select id="view"><option value="summary">Model / task summaries</option><option value="runs">Individual attempts</option></select></label>\n<label>Search <input id="search" placeholder="Model, task, outcome…" type="search"></label>\n<button id="reset">Reset view</button><div id="count" aria-live="polite"></div>\n<div class="scroll"><table><thead id="head"></thead><tbody id="body"></tbody></table></div>\n<p><small>This is a static snapshot. Run the reporter again after new tests, then open the newly generated page. Dates are UTC. CSV files remain available as exports, but you do not need to use them.</small></p>\n<script id="data" type="application/json">__DATA__</script>\n<script>\nconst data=JSON.parse(document.getElementById(\'data\').textContent);\nconst schemas={summary:[[\'model\',\'Model\'],[\'task\',\'Task\'],[\'task_version\',\'Task version\'],[\'grader_version\',\'Grader version\'],[\'success_percent\',\'Success %\'],[\'median_successful_workflow_seconds\',\'Median successful workflow (s)\'],[\'total_attempts\',\'Total attempts\'],[\'valid_attempts\',\'Valid attempts\'],[\'passes\',\'Passes\'],[\'failures\',\'Failures\'],[\'infrastructure_errors\',\'Attempts with infrastructure errors\'],[\'invalid_data\',\'Invalid data attempts\'],[\'latest_test_utc\',\'Latest test (UTC)\'],[\'context_size\',\'Context\'],[\'quantization\',\'Model quantization\'],[\'gpu_placement\',\'GPU placement\'],[\'kv_precision\',\'KV precision\'],[\'sampling\',\'Sampling\'],[\'mtp\',\'MTP\'],[\'image\',\'Image\'],[\'successful_runs_with_timing\',\'Timed successful runs\'],[\'median_successful_agent_seconds\',\'Median successful agent (s)\'],[\'successful_runs_with_agent_timing\',\'Agent-timed successful runs\'],[\'code_fingerprint_scheme\',\'Fingerprint scheme\'],[\'code_fingerprint\',\'Code fingerprint\'],[\'provenance\',\'Provenance\'],[\'code_commits\',\'Code commits\'],[\'code_tree_dirty_states\',\'Tree dirty states\'],[\'other_outcomes\',\'Other outcomes\']],runs:[[\'model\',\'Model\'],[\'task\',\'Task\'],[\'task_version\',\'Task version\'],[\'grader_version\',\'Grader version\'],[\'outcome\',\'Outcome\'],[\'task_score\',\'Task score\'],[\'total_workflow_seconds\',\'Total workflow (s)\'],[\'agent_process_seconds\',\'Agent process (s)\'],[\'reported_session_seconds\',\'Session-reported (s)\'],[\'agent_termination\',\'Agent termination\'],[\'agent_timeout\',\'Agent timeout\'],[\'test_date_utc\',\'Test date (UTC)\'],[\'run\',\'Run\'],[\'context_size\',\'Context\'],[\'quantization\',\'Model quantization\'],[\'gpu_placement\',\'GPU placement\'],[\'kv_precision\',\'KV precision\'],[\'sampling\',\'Sampling\'],[\'mtp\',\'MTP\'],[\'evidence_directory\',\'Evidence (project-relative)\'],[\'code_fingerprint_scheme\',\'Fingerprint scheme\'],[\'code_fingerprint\',\'Code fingerprint\'],[\'provenance\',\'Provenance\'],[\'code_commit\',\'Code commit\'],[\'code_tree_dirty\',\'Tree dirty\'],[\'infrastructure_errors\',\'Infrastructure error entries\'],[\'image\',\'Image\']]};\nconst numeric=new Set([\'success_percent\',\'median_successful_workflow_seconds\',\'total_attempts\',\'valid_attempts\',\'passes\',\'failures\',\'infrastructure_errors\',\'invalid_data\',\'successful_runs_with_timing\',\'other_outcomes\',\'task_score\',\'total_workflow_seconds\',\'agent_process_seconds\',\'reported_session_seconds\',\'median_successful_agent_seconds\',\'successful_runs_with_agent_timing\']);\nlet sortKey=null,ascending=true;\nconst view=document.getElementById(\'view\'),search=document.getElementById(\'search\');\nfunction missing(v){return v===null||v===undefined||v===\'\'||v===\'unknown\'}\nfunction render(){\n const kind=view.value,cols=schemas[kind],query=search.value.trim().toLowerCase();\n let rows=data[kind].filter(r=>Object.values(r).some(v=>String(v).toLowerCase().includes(query)));\n if(sortKey)rows.sort((a,b)=>{let x=a[sortKey],y=b[sortKey];if(missing(x)||missing(y))return missing(x)===missing(y)?0:missing(x)?1:-1;let cmp=numeric.has(sortKey)&&kind===\'summary\'||numeric.has(sortKey)&&sortKey!==\'infrastructure_errors\'?Number(x)-Number(y):String(x).localeCompare(String(y),undefined,{numeric:true});return ascending?cmp:-cmp});\n const head=document.getElementById(\'head\');head.replaceChildren();const tr=document.createElement(\'tr\');\n for(const [key,label] of cols){const th=document.createElement(\'th\'),b=document.createElement(\'button\');th.scope=\'col\';b.textContent=label+(sortKey===key?(ascending?\' ▲\':\' ▼\'):\' ↕\');b.onclick=()=>{ascending=sortKey===key?!ascending:true;sortKey=key;render()};th.append(b);tr.append(th)}head.append(tr);\n const body=document.getElementById(\'body\');body.replaceChildren();for(const r of rows){const t=document.createElement(\'tr\');for(const [key] of cols){const c=document.createElement(\'td\');c.textContent=missing(r[key])?\'Not recorded\':String(r[key]);if(key===\'outcome\')c.className=r[key]===\'pass\'?\'good\':\'bad\';t.append(c)}body.append(t)}\n document.getElementById(\'count\').textContent=rows.length+\' of \'+data[kind].length+\' rows shown\';\n}\nview.onchange=()=>{sortKey=null;render()};search.oninput=render;document.getElementById(\'reset\').onclick=()=>{search.value=\'\';sortKey=null;ascending=true;render()};render();\n</script></html>'
BAR = '=' * 72
print(f'\n{BAR}\nBEGIN OUTPUT TO COPY\n{BAR}', flush=True)
try:
    base = Path(sys.argv[1]).expanduser() if len(sys.argv) > 1 else Path.home() / 'hermes-eval'
    if (base / 'summary.csv').is_file():
        report = base
    else:
        candidates = sorted((base / 'reports').glob('report-*/summary.csv'))
        if not candidates:
            raise RuntimeError('No CSV reports found. Run the results reporter first.')
        report = candidates[-1].parent
    data = {}
    for key, name in [('summary', 'summary.csv'), ('runs', 'runs.csv')]:
        with (report / name).open(encoding='utf-8-sig', newline='') as f:
            data[key] = list(csv.DictReader(f))
    encoded = json.dumps(data, ensure_ascii=True).replace('<', '\\u003c')
    html = PAGE.replace('__DATA__', encoded)
    output = report / ('dashboard-' + datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S.%fZ') + '.html')
    with output.open('x', encoding='utf-8') as f:
        f.write(html)
    print(f'SOURCE REPORT: {report}')
    print(f'Summary rows: {len(data["summary"])}; attempts: {len(data["runs"])}')
    print(f'WEBPAGE: {output}')
    print('Double-click that HTML file to open it in your browser.')
    print('No inference was run. Existing CSV reports and run evidence were not modified.')
except Exception as exc:
    print(f'ERROR: {type(exc).__name__}: {exc}')
    sys.exit(3)
finally:
    print(f'\n{BAR}\nEND OUTPUT TO COPY\n{BAR}', flush=True)
